"""Factory #246 TEST_ONLY rule/price projection and adversarial boundary tests."""
from __future__ import annotations

import copy
import unittest

from research_wp_r0.aql_factory_authentic_research_admission import (
    ResearchAdmissionError, _digest, seal,
)
from research_wp_r0.aql_factory_historical_rule_projection import (
    evaluate_historical_rules,
)
from research_wp_r0.indicator_library_v2 import IndicatorRegistryV2
from research_wp_r0.strategy_definition import StrategyDefinition


def definition():
    # Faithful F006 ROC strategy grammar as generated by Discoverer #230;
    # parameters reduced for a bounded artificial warmup fixture.
    spec = {
        "schema_version": "1", "strategy_id": "f006-v1",
        "strategy_version": "v1", "scope": "RESEARCH_ONLY",
        "indicators": [{
            "name": "roc", "indicator_id": "ROC_v2", "version": "2",
            "parameters": {"period": 5},
            "constraints": {"period": {"type": "int", "min": 1, "max": 1000}},
        }],
        "entry": {
            "op": "gt",
            "left": {"op": "indicator", "name": "roc", "field": "roc", "lag": 0},
            "right": {"op": "constant", "value": 1.0},
        },
        "exit": {
            "op": "gt",
            "left": {"op": "constant", "value": -1.0},
            "right": {"op": "indicator", "name": "roc", "field": "roc", "lag": 0},
        },
        "timing": {"decision": "CONFIRMED_CLOSE",
                   "entry_execution": "NEXT_ELIGIBLE_OPEN",
                   "ambiguity": "REJECT"},
        "risk": {"unit": "ENTRY_NOTIONAL", "max_exposure": 0.01,
                 "max_leverage": 1, "stop_fraction": .5,
                 "target_fraction": .9, "entry_ttl_bars": 3,
                 "holding_bars": 3},
    }
    return StrategyDefinition(spec, registry=IndicatorRegistryV2()).to_dict()


def fixture():
    defn = definition()
    plan = _digest({"plan": "TEST_ONLY_53_FROZEN"})
    bars = []
    for i in range(24):
        start = (1000+i)*60_000
        price = 100.0 + 2.0*i
        row = {
            "open_ms": start, "close_ms": start+59_999,
            "open": price, "high": price+1.0,
            "low": price-1.0, "close": price+.5,
            "volume": 10.0, "quality": "FINAL",
            "known_at_ms": start+60_000,
        }
        row["bar_sha256"] = _digest(row)
        bars.append(row)
    trials = [
        {"attempt_id": "attempt-%02d" % i,
         "candidate_digest": defn["digest"] if i == 0 else
                             _digest({"attempt": i}),
         "plan_digest": plan, "state": "PROPOSED",
         "duplicate_of": None}
        for i in range(53)
    ]
    return {
        "schema": "aql.factory.historical-rule-projection.v1",
        "source_kind": "TEST_ONLY", "market": "SPOT",
        "availability": "SYNTHETIC_TEST",
        "holdout": "SEALED_UNOPENED", "execution_authority": "NONE",
        "dataset_id": "SYNTHETIC_ORIGINAL_GRID",
        "dataset_version": 1,
        "source_bytes_sha256": "a"*64,
        "source_manifest_sha256": "b"*64,
        "plan_digest": plan, "trial_budget": 53,
        "trials": trials, "selected_attempt_id": "attempt-00",
        "strategy": defn, "direction": "LONG", "width_ms": 60_000,
        "universe": {"full": 4, "eligible": 3, "ineligible": 1,
                     "unscanned": 1, "rejected": 1, "unknown": 0,
                     "nominated": 1,
                     "source_coverage": "NOT_INDEPENDENTLY_ATTESTED"},
        "opportunity_count": 0, "opportunities": [], "bars": bars,
        "costs": {"fee_entry_bps": "5", "fee_exit_bps": "5",
                  "spread_entry_bps": "2", "spread_exit_bps": "2",
                  "slippage_entry_bps": "3", "slippage_exit_bps": "3",
                  "funding_bps_per_bar": "0"},
    }


def repin_bar(p, i):
    row = p["bars"][i]
    row["bar_sha256"] = _digest({k: v for k, v in row.items()
                                if k != "bar_sha256"})


class TestHistoricalRuleProjection(unittest.TestCase):
    def test_real_kernels_rule_triggers_next_open_and_modeled_costs(self):
        p = fixture()
        before = copy.deepcopy(p)
        a = evaluate_historical_rules(seal(p))
        b = evaluate_historical_rules(seal(p))
        self.assertEqual(a, b)
        self.assertEqual(p, before)
        self.assertEqual(a["trial_budget"], 53)
        self.assertEqual(sum(a["trial_state_counts"].values()), 53)
        self.assertEqual(a["decision_slots"], len(p["bars"])-1)
        self.assertEqual(sum(a["decision_counts"].values()), a["decision_slots"])
        self.assertGreater(a["decision_counts"].get("ENTRY_TRIGGERED", 0), 0)
        self.assertGreater(a["decision_counts"].get("EXIT_TRIGGERED", 0), 0)
        self.assertEqual(a["modeled_outcomes"][0]["exit_reason"], "HOLDING_CAP")
        self.assertEqual(a["modeled_outcomes"][0]["holding_bars"], 3)
        self.assertEqual(a["modeled_outcomes"][0]["total_cost_bps"], "20")
        self.assertIsNotNone(a["modeled_outcomes"][0]["modeled_net_return"])
        self.assertEqual(a["scientific_result"], "INSUFFICIENT_EVIDENCE")
        self.assertFalse(a["historical_pit_verified"])
        self.assertEqual(a["execution_status"], "NOT_OBSERVED")
        self.assertEqual(a["artifact_sha256"],
                         _digest({k:v for k,v in a.items()
                                  if k != "artifact_sha256"}))

    def test_retrospective_original_never_automatically_pit(self):
        p = fixture()
        p["source_kind"] = "ORIGINAL_UNVERIFIED"
        p["availability"] = "RETROSPECTIVE_NON_PIT"
        for i, row in enumerate(p["bars"]):
            row["known_at_ms"] = None
            repin_bar(p, i)
        result = evaluate_historical_rules(seal(p))
        self.assertEqual(result["model_class"], "RETROSPECTIVE_ONLY_UNVERIFIED")
        self.assertEqual(result["unverified_known_at_count"], len(p["bars"]))
        self.assertFalse(result["source_original_bytes_verified"])
        self.assertEqual(result["scientific_result"], "INSUFFICIENT_EVIDENCE")

    def test_intrabar_barrier_is_unknown_not_winner(self):
        p = fixture()
        p["strategy"]["definition"]["risk"]["target_fraction"] = .0001
        p["strategy"] = StrategyDefinition(
            p["strategy"]["definition"], registry=IndicatorRegistryV2()).to_dict()
        p["trials"][0]["candidate_digest"] = p["strategy"]["digest"]
        out = evaluate_historical_rules(seal(p))
        self.assertGreater(out["unknown_outcomes"], 0)
        self.assertIsNone(out["modeled_outcomes"][0]["modeled_net_return"])
        self.assertEqual(out["modeled_outcomes"][0]["status"],
                         "UNKNOWN_INTRABAR_STOP_TARGET")

    def test_prefix_does_not_read_future_prices(self):
        x = fixture()
        first = evaluate_historical_rules(seal(x))
        y = fixture()
        for i in range(20, len(y["bars"])):
            b = y["bars"][i]
            b.update(open=1000., high=1001., low=999., close=1000., volume=1.)
            repin_bar(y, i)
        second = evaluate_historical_rules(seal(y))
        self.assertEqual(first["decisions"][:18], second["decisions"][:18])

    def test_negative_matrix(self):
        cases = [
            ("future-feature", lambda p: p["bars"][8].update(known_at_ms=p["bars"][8]["close_ms"]+2)),
            ("missing-bar", lambda p: p["bars"].pop(6)),
            ("duplicate-bar", lambda p: p["bars"].insert(6, copy.deepcopy(p["bars"][5]))),
            ("bad-price", lambda p: p["bars"][5].update(low=999.0)),
            ("unfinal", lambda p: p["bars"][5].update(quality="PARTIAL")),
            ("trial-52", lambda p: p["trials"].pop()),
            ("trial-54", lambda p: p["trials"].append(copy.deepcopy(p["trials"][0]))),
            ("trial-id-duplicate", lambda p: p["trials"][1].update(attempt_id="attempt-00")),
            ("trial-hash", lambda p: p["trials"][0].update(candidate_digest="1"*64)),
            ("trial-plan", lambda p: p["trials"][0].update(plan_digest="1"*64)),
            ("universe", lambda p: p["universe"].update(nominated=2)),
            ("universe-promotion", lambda p: p["universe"].update(source_coverage="ATTESTED")),
            ("bad-opportunity-count", lambda p: p.update(opportunity_count=1)),
            ("bad-holdout", lambda p: p.update(holdout="OPEN")),
            ("cost-drift", lambda p: p["costs"].update(fee_entry_bps="-1")),
            ("cost-missing", lambda p: p["costs"].pop("spread_entry_bps")),
            ("fake-pit", lambda p: p.update(availability="CONFIRMED_PIT")),
            ("fake-source", lambda p: p.update(source_kind="AUTHENTIC_VERIFIED")),
            ("spot-short", lambda p: p.update(direction="SHORT")),
            ("strategy-override", lambda p: p["strategy"]["definition"]["risk"].update(holding_bars=1)),
            ("duplicate-parent-missing", lambda p: p["trials"][2].update(state="DUPLICATE", duplicate_of="MISSING")),
            ("duplicate-parent-future", lambda p: p["trials"][2].update(state="DUPLICATE", duplicate_of="attempt-10")),
        ]
        for label, mutate in cases:
            with self.subTest(label=label):
                p = fixture()
                mutate(p)
                if label in ("future-feature", "bad-price", "unfinal"):
                    repin_bar(p, 8 if label == "future-feature" else 5)
                with self.assertRaises((ResearchAdmissionError, ValueError)):
                    evaluate_historical_rules(seal(p))

    def test_tampered_bar_or_packet_rejected(self):
        p = fixture()
        p["bars"][8]["close"] = 9999
        with self.assertRaises(ResearchAdmissionError):
            evaluate_historical_rules(seal(p))
        s = seal(fixture())
        s["costs"]["fee_entry_bps"] = "500"
        with self.assertRaises(ResearchAdmissionError):
            evaluate_historical_rules(s)


if __name__ == "__main__":
    unittest.main()
